// Embedded SPIR-V (generated by vgrid_embed_shaders onto a PRIVATE include
// path).
#include "rans_decode_comp.spv.hpp"
#include "rans_slots_comp.spv.hpp"
#include "rans_verdict_comp.spv.hpp"
#include "survivor_ranks_comp.spv.hpp"

namespace volumetric_kit::grid::codec::detail {
namespace {

// The kernels' workgroup widths; survivor_ranks.comp is one workgroup.
constexpr std::uint32_t kSlotsLanes = 256;
constexpr std::uint32_t kDecodeLanes = 1;
constexpr std::uint32_t kVerdictLanes = 64;

static_assert((kMaxFrameSegments - 1) << 2 < kNoVerdict - 3,
              "a failing segment's verdict word is below kNoVerdict");

constexpr VkDeviceSize kVerdictBytes = 2 * sizeof(std::uint32_t);

}  // namespace

core::Result<std::unique_ptr<DeviceFrameReader>> DeviceFrameReader::create(
    core::Device& device, core::Allocator& allocator) {
  VKC_TRY(check_device_requirements(device, "DeviceFrameReader::create"));
  std::unique_ptr<DeviceFrameReader> owned(new DeviceFrameReader());
  DeviceFrameReader& r = *owned;
  r.device_ = &device;
  r.allocator_ = &allocator;
  VkPushConstantRange push{};
  push.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
  push.size = sizeof(RansPush);
  core::KernelSetBuilder kb(device);
  VKC_TRY(kb.add(r.slots_kernel_, "codec_rans_slots", vgrid_rans_slots_comp_spv,
                 vgrid_rans_slots_comp_spv_size, 2, &push));
  VKC_TRY(kb.add(r.decode_kernel_, "codec_rans_decode",
                 vgrid_rans_decode_comp_spv, vgrid_rans_decode_comp_spv_size, 8,
                 &push));
  VKC_TRY(kb.add(r.verdict_kernel_, "codec_rans_verdict",
                 vgrid_rans_verdict_comp_spv, vgrid_rans_verdict_comp_spv_size,
                 3, &push));
  VKC_TRY(kb.add(r.ranks_kernel_, "codec_survivor_ranks",
                 vgrid_survivor_ranks_comp_spv,
                 vgrid_survivor_ranks_comp_spv_size, 3, &push));
  VKC_ASSIGN(r.pool_, kb.build());
  VkPhysicalDeviceProperties props{};
  vkGetPhysicalDeviceProperties(device.physical_device(), &props);
  r.max_workgroup_count_x_ = props.limits.maxComputeWorkGroupCount[0];
  r.max_storage_buffer_range_ = props.limits.maxStorageBufferRange;
  r.min_offset_alignment_ =
      std::max<VkDeviceSize>(props.limits.minStorageBufferOffsetAlignment, 4);
  // The verdict, and the ranks of a frame with no reference entries, which
  // even a frame of no segments hands the merge.
  VKC_TRY(core::ensure_device_scratch(
      device, allocator, r.verdict_, kVerdictBytes, r.max_storage_buffer_range_,
      "codec.rans_verdict"));
  VKC_TRY(core::ensure_device_scratch(
      device, allocator, r.ranks_, sizeof(std::uint32_t),
      r.max_storage_buffer_range_, "codec.survivor_ranks"));
  return owned;
}

core::Result<ResidentBlocks> DeviceFrameReader::record_decode(
    core::CommandBatch& batch, const ParsedFrame& frame, VkBuffer input,
    VkDeviceSize input_bytes, VkDeviceSize payload_at,
    core::GpuStageScope* stage) {
  VKC_TRY(
      check_frame_type(frame.header.type, "DeviceFrameReader::record_decode"));
  const FrameType type = frame.header.type;
  const bool inter = type == FrameType::kInter;
  const std::uint32_t n = frame.header.block_count;
  const std::uint32_t k = frame.header.params.coefficient_count;
  const std::uint32_t r_size = frame.header.segment_size;
  // An intra frame is M = 0: its blocks are all new.
  const std::uint32_t m = inter ? frame.reference.header.block_count : 0;
  const std::uint32_t u_size = inter ? frame.update_size : 0;
  const std::uint32_t a = inter ? frame.new_count : n;
  const std::uint32_t entries = m + a;  // below 2^32 (parse_frame)
  const auto segments =
      static_cast<std::uint32_t>(frame.segment_lengths.size());
  // One invocation decodes a whole segment, so the rule parse_frame holds
  // the sizes to is what bounds it; checked again, as the type is, on a
  // caller's parsed frame.
  VKC_TRY(check_segment_size("DeviceFrameReader::record_decode", "segment size",
                             r_size));
  if (inter) {
    VKC_TRY(check_segment_size("DeviceFrameReader::record_decode",
                               "update size", u_size));
  }
  // The verdict reset, once nothing else can refuse the frame, which a frame
  // of no segments leaves as it is.
  auto reset = [&]() -> core::Status {
    VKC_TRY(batch.fill(verdict_, 0, sizeof(std::uint32_t), kNoVerdict));
    VKC_TRY(
        batch.fill(verdict_, sizeof(std::uint32_t), sizeof(std::uint32_t), 0u));
    return {};
  };
  ResidentBlocks out;
  out.coefficient_count = k;
  out.ranks = &ranks_;
  if (segments == 0) {
    VKC_TRY(reset());
    return out;
  }
  // The payload, bound from its offset aligned down to what a binding allows,
  // read from the byte after (pc.payload_byte), to the word its last byte is
  // in -- inside the record's slack.
  const VkDeviceSize bind_at = payload_at - payload_at % min_offset_alignment_;
  const VkDeviceSize payload_byte = payload_at - bind_at;
  const VkDeviceSize payload_bytes =
      (payload_byte + frame.payload_size + 3) & ~VkDeviceSize{3};
  if (payload_at > input_bytes || payload_bytes > input_bytes - bind_at) {
    return core::Status::invalid_argument(
        "DeviceFrameReader::record_decode: the payload lies past the input");
  }

  // Every size first, so a frame the device cannot hold grows nothing.
  const std::vector<std::uint32_t> table_entries =
      rans_table_entries(frame.tables);
  const std::uint32_t models = frame_model_count(type, k);
  const VkDeviceSize entry_bytes = table_entries.size() * sizeof(std::uint32_t);
  const VkDeviceSize slot_bytes =
      VkDeviceSize(models) * kRansScale * sizeof(std::uint32_t);
  const VkDeviceSize word_bytes =
      (VkDeviceSize(segments) + 1) * sizeof(std::uint32_t);
  const VkDeviceSize list_bytes = VkDeviceSize(a) * sizeof(volume::BlockIndex);
  const VkDeviceSize mask_bytes =
      VkDeviceSize(entries) * kMaskWordsPerBlock * sizeof(std::uint32_t);
  const VkDeviceSize coeff_bytes =
      VkDeviceSize(entries) * coefficient_words(k) * sizeof(std::uint32_t);
  const VkDeviceSize mode_bytes = VkDeviceSize(m) * sizeof(std::uint32_t);
  const VkDeviceSize fault_bytes =
      VkDeviceSize(segments) * sizeof(std::uint32_t);
  const VkDeviceSize rank_bytes = (VkDeviceSize(m) + 1) * sizeof(std::uint32_t);
  struct Scratch {
    core::Buffer& buffer;
    VkDeviceSize bytes;
    const char* name;
  };
  const Scratch scratch[] = {
      {tables_, entry_bytes, "codec.rans_decode_tables"},
      {slots_, slot_bytes, "codec.rans_slots"},
      {segment_words_, word_bytes, "codec.rans_segment_words"},
      {list_, binding_range(list_bytes, sizeof(volume::BlockIndex)),
       "codec.rans_decode_list"},
      {masks_, mask_bytes, "codec.rans_decode_masks"},
      {coefficients_, coeff_bytes, "codec.rans_decode_coefficients"},
      {modes_, binding_range(mode_bytes, sizeof(std::uint32_t)),
       "codec.rans_decode_modes"},
      {faults_, fault_bytes, "codec.rans_faults"},
      {ranks_, rank_bytes, "codec.survivor_ranks"},
  };
  const VkDeviceSize range = max_storage_buffer_range_;
  VKC_TRY(core::check_storage_buffer_range("codec.decode_input", payload_bytes,
                                           range));
  for (const Scratch& b : scratch) {
    VKC_TRY(core::check_storage_buffer_range(b.name, b.bytes, range));
  }
  for (const Scratch& b : scratch) {
    VKC_TRY(core::ensure_device_scratch(*device_, *allocator_, b.buffer,
                                        b.bytes, range, b.name));
  }
  // Each segment's first 16-bit word. The lengths sum to the payload, which
  // the range check above holds under 4 GiB, so every offset fits.
  std::vector<std::uint32_t> segment_words(std::size_t(segments) + 1, 0);
  for (std::uint32_t s = 0; s < segments; ++s) {
    segment_words[s + 1] = segment_words[s] + frame.segment_lengths[s] / 2;
  }
  VKC_TRY(reset());

  // Inline, as the decode's batch writes every update ahead of its first
  // dispatch.
  VKC_TRY(batch.upload(tables_, 0, table_entries.data(), entry_bytes));
  VKC_TRY(batch.upload(segment_words_, 0, segment_words.data(), word_bytes));

  slots_kernel_.set.write_storage_buffer(0, tables_.handle(), 0, entry_bytes);
  slots_kernel_.set.write_storage_buffer(1, slots_.handle(), 0, slot_bytes);
  core::ComputeKernel& decode = decode_kernel_;
  decode.set.write_storage_buffer(0, slots_.handle(), 0, slot_bytes);
  decode.set.write_storage_buffer(1, input, bind_at, payload_bytes);
  decode.set.write_storage_buffer(2, segment_words_.handle(), 0, word_bytes);
  decode.set.write_storage_buffer(
      3, list_.handle(), 0,
      binding_range(list_bytes, sizeof(volume::BlockIndex)));
  decode.set.write_storage_buffer(4, masks_.handle(), 0, mask_bytes);
  decode.set.write_storage_buffer(5, coefficients_.handle(), 0, coeff_bytes);
  decode.set.write_storage_buffer(6, faults_.handle(), 0, fault_bytes);
  decode.set.write_storage_buffer(
      7, modes_.handle(), 0, binding_range(mode_bytes, sizeof(std::uint32_t)));
  const core::DescriptorSet& verdict = verdict_kernel_.set;
  verdict.write_storage_buffer(0, faults_.handle(), 0, fault_bytes);
  verdict.write_storage_buffer(
      1, list_.handle(), 0,
      binding_range(list_bytes, sizeof(volume::BlockIndex)));
  verdict.write_storage_buffer(2, verdict_.handle(), 0, kVerdictBytes);
  const core::DescriptorSet& ranks = ranks_kernel_.set;
  ranks.write_storage_buffer(0, modes_.handle(), 0,
                             binding_range(mode_bytes, sizeof(std::uint32_t)));
  ranks.write_storage_buffer(1, ranks_.handle(), 0, rank_bytes);
  ranks.write_storage_buffer(2, verdict_.handle(), 0, kVerdictBytes);

  RansPush push;
  push.num_entries = entries;
  push.coefficient_count = k;
  push.segment_size = r_size;
  push.segment_count = segments;
  push.frame_type = static_cast<std::uint32_t>(type);
  push.reference_count = m;
  push.update_size = u_size;
  push.payload_byte = static_cast<std::uint32_t>(payload_byte);
  VKC_TRY(dispatch_items(batch, slots_kernel_, push,
                         std::uint64_t(models) * kRansScale, kSlotsLanes,
                         max_workgroup_count_x_, stage));
  VKC_TRY(dispatch_items(batch, decode, push, segments, kDecodeLanes,
                         max_workgroup_count_x_, stage));
  VKC_TRY(dispatch_items(batch, verdict_kernel_, push, segments, kVerdictLanes,
                         max_workgroup_count_x_, stage));
  VKC_TRY(batch.dispatch(ranks_kernel_, &push, sizeof(push), 1,
                         max_workgroup_count_x_, stage));

  out.list = &list_;
  out.masks = &masks_;
  out.coefficients = &coefficients_;
  out.modes = m != 0 ? &modes_ : nullptr;
  out.count = entries;
  out.reference_count = m;
  return out;
}

core::Status DeviceFrameReader::judge(FrameType type, std::uint32_t n,
                                      std::uint32_t a, std::uint32_t failed,
                                      std::uint32_t survivors) {
  if (failed != kNoVerdict) {
    VKC_TRY(check_segment(failed >> 2, static_cast<SegmentFault>(failed & 3u)));
  }
  if (type != FrameType::kInter) return {};
  return check_survivors(survivors, n, a);
}

}  // namespace volumetric_kit::grid::codec::detail
